theorem ProbabilityTheory.extracted_1.{u_13, u_12, u_1} {Ω : Type u_1} {mΩ : MeasurableSpace Ω} {μ : Measure Ω}
  {ι : Type u_12} {β : ι → Type u_13} [inst : Fintype ι] (f : (x : ι) → Ω → β x) [m : (x : ι) → MeasurableSpace (β x)]
  [inst_1 : IsProbabilityMeasure μ] (hf : ∀ (x : ι), Measurable (f x)) {h : (i : ι) → Set (β i)}
  (hm : ∀ (i : ι), MeasurableSet (h i)) :
